Definition fbp_RW (ff fp : Z) : list (Z * Z) := [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z.

Ltac fs_bundle_now HH RFc ACc SK2 FF MU3 WM3 W3K RFx ACx SKx :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of SK2 with stack0 _ ?lo ?shi => lazymatch type of RFc with as_RFS ?H ?LFc _ =>
    let B := fresh "BND" in
    assert (B : as_RFS H LFc mc /\ ACONST mc /\ stack0 mc lo shi)
      by (eapply (fs_frame_writes_pl _ HH); [exact RFc| exact ACc| exact SK2| exact FF| exact MU3| exact WM3| exact W3K]);
    destruct B as (RFx & ACx & SKx) end end end.
(* [comment removed for export] *)
Ltac acc_now AC MU3 WFR F1 F3 SEP ACn :=
  lazymatch type of AC with accessible _ ?O ?n =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    assert (ACn : accessible mc O n)
      by (eapply (accessible_transport_fr _ _ mc O n _ 16); [exact AC| exact MU3| exact WFR| clear - F1; lia| exact F3| clear; lia| clear - SEP; unhideL; lia])
  end end.

(* [comment removed for export] *)
Lemma nb_ok : forall b e, (0 < b /\ 0 < e) \/ (b = 0 /\ e = 0) -> Z.lxor (Z.b2z (0 <? b)) (Z.b2z (e <? 1)) = 1.
Proof. intros b e K. destruct (Z.ltb_spec 0 b); destruct (Z.ltb_spec e 1); cbn; first [reflexivity | exfalso; lia]. Qed.

