Definition fbp_seg1_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (fb n lo shi : Z) (FB : fbv) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t1 t2 t3 t4 t5 t6 m' (spa ff fp : Z) (gap : list cell) (tj hjunk sh16 : list byte),
    ms' = MS (mkR (Z_to_bv 64 AFBP_RET_FS) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1 t2
                  sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (fb_out FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb + 40)) (Z_to_bv 64 (fb_end FB - fb_out FB)) (Z_to_bv 64 u64max)
                  (Z_to_bv 64 (fb_end FB)) (Z_to_bv 64 ff) (Z_to_bv 64 n)
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880))
                  (Z_to_bv 64 (fb + 8)) (Z_to_bv 64 (fb_out FB - fb_in FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (fb + 16))
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3 t4 t5 t6)
             F (Z_to_bv 64 AFBP_TA) fc None m' (seg_rom bsegs)
    /\ munch (fs_W5 H lo (bv_unsigned sp) fp ff 1) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240)
    /\ stk bsegs m' lo spa
    /\ rw_cells bsegs m' spa [CB 88 tj; C8 (Z_to_bv 64 ff)]
    /\ rw_cells bsegs m' (spa + 96) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa
    /\ rw_cells bsegs m' (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)]
    /\ rw_cells bsegs m' (Z.shiftr ff 3 + 2147450880) [CB 16 sh16]
    /\ rw_cells bsegs m' fp [C1 (b8 1)]
    /\ rw_cells bsegs m' fb (FlatBufCells FB)
    /\ accessible m' fb SZ_FB
    /\ fresh_frame H LF 1 ff fp /\ as_RFS H ((1, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma fbp_seg1 : forall (ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (LF : list fframe) (fb n lo shi : Z) (FB : fbv),
  rw_cells bsegs m fb (FlatBufCells FB) -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) -> fsobj H LF fb SZ_FB -> accessible m fb SZ_FB ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= n -> fb_size FB + n < 2^27 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 240 + AFS_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (fbp_seg1_post sp gp tp F fc LF fb n lo shi FB ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 fb) (Z_to_bv 64 n) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FB_PREPARE) fc None m (seg_rom bsegs)).
