(* [comment removed for export] *)
Definition fbp_end_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (W : list (Z * Z)) (lo shi fb outv n : Z) (FB' : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 outv) (Z_to_bv 64 n) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch W m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ (rw_cells bsegs m' fb (FlatBufCells FB') /\ accessible m' fb SZ_FB)
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Definition fbp_WA (fb ff fp : Z) : list (Z * Z) := (fb, fb + SZ_FB) :: fbp_RW ff fp.

(* [comment removed for export] *)
Lemma fbp_A : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t1' t2' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp : Z) (FB : fbv)
    (m0 mx : mem) (gap : list cell) (tj hjunk sh16 : list byte),
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa [CB 88 tj; C8 (Z_to_bv 64 ff)] ->
  rw_cells bsegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 (b8 1)] ->
  rw_cells bsegs mx fb (FlatBufCells FB) -> accessible mx fb SZ_FB -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) -> fsobj H LF fb SZ_FB ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi -> mem_inv bsegs mx -> as_RFS H LF m0 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  (fb_begin FB = 0 -> fb_end FB = 0) ->      (* [comment removed for export] *)
  0 <= n -> fb_size FB + n < 2^27 -> n <= fb_end FB - fb_out FB ->
  lo + 240 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
