(* [comment removed for export] *)
Definition fbp_tmp2 (tj0 tj1 : list byte) (fb ff : Z) : list cell :=
  [CB 56 tj0; C8 (Z_to_bv 64 (Z.shiftr fb 3 + 2147450880)); CB 24 tj1; C8 (Z_to_bv 64 ff)].

Definition fbp_seg2_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (fb n lo spa ff : Z) (FB : fbv) (t1 t2 t3 t4 t5 t6 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' (tj0 tj1 : list byte),
    ms' = MS (mkR (Z_to_bv 64 AFBP_RET_FS) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1 t2
                  sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (fb_out FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb + 40)) (Z_to_bv 64 (fb_begin FB)) (Z_to_bv 64 u64max)
                  (Z_to_bv 64 (fb_cap FB - fb_size FB)) (Z_to_bv 64 ff) (Z_to_bv 64 n)
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880))
                  (Z_to_bv 64 (fb + 8)) (Z_to_bv 64 (fb_size FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (fb + 16))
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3 t4 t5 t6)
             F (Z_to_bv 64 AFBP_TB) fc None m' (seg_rom bsegs)
    /\ munch [(spa, spa + 96)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ rw_cells bsegs m' spa (fbp_tmp2 tj0 tj1 fb ff).

(* [comment removed for export] *)
Lemma fbp_seg2 : forall (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (t1' t2' t3' t4' t5' t6' : word) (fb n lo spa ff : Z) (FB : fbv) (mx : mem) (tj : list byte),
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa [CB 88 tj; C8 (Z_to_bv 64 ff)] ->
  rw_cells bsegs mx fb (FlatBufCells FB) -> accessible mx fb SZ_FB -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) ->
  ACONST mx -> mem_inv bsegs mx ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= n -> fb_size FB + n < 2^27 -> fb_end FB - fb_out FB < n -> 0 <= ff < 2^64 ->
  lo + 240 <= bv_unsigned sp -> aceil <= lo ->
  evt bsegs (fbp_seg2_post sp gp tp F fc fb n lo spa ff FB t1' t2' t3' t4' t5' t6' mx)
    (MS (mkR (Z_to_bv 64 AFBP_RET_FS) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1' t2'
                  sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (fb_out FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb + 40)) (Z_to_bv 64 (fb_end FB - fb_out FB)) (Z_to_bv 64 u64max)
                  (Z_to_bv 64 (fb_end FB)) (Z_to_bv 64 ff) (Z_to_bv 64 n)
                  (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880))
                  (Z_to_bv 64 (fb + 8)) (Z_to_bv 64 (fb_out FB - fb_in FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (fb + 16))
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3' t4' t5' t6')
        F (Z_to_bv 64 AFBP_TA) fc None mx (seg_rom bsegs)).
